  // Hour Glass. Layers, bottom to top: a photographic sand texture (a picture, still), this canvas, the glass (a picture the watch turns).
  // The glass is see-through inside; the canvas paints the EMPTY part of each bulb in the dark glass colour, so the sand texture shows exactly
  // where there is sand. Each frame the sand is worked out from the bulb geometry: a level cut by area, a cone pile, a crater. At every
  // minute change the glass turns over (ease in-out); the sand keeps a level surface while it turns and starts to pour after 90 degrees.
  const DATA = {"UP":[[36.0,6],[34.0,8],[32.0,10],[29.0,12],[27.0,14],[25.0,16],[23.0,18],[21.5,20],[20.0,22],[19.0,24],[18.5,26],[17.5,28],[17.0,30],[16.5,32],[16.0,34],[16.0,36],[16.0,38],[16.0,40],[16.0,42],[16.0,44],[16.0,46],[16.5,48],[17.0,50],[17.5,52],[18.0,54],[18.5,56],[19.5,58],[20.0,60],[21.0,62],[22.0,64],[23.0,66],[24.0,68],[25.5,70],[27.0,72],[28.0,74],[29.5,76],[31.0,78],[32.5,80],[34.5,82],[36.0,84],[37.5,86],[39.5,88],[41.5,90],[43.5,92],[45.5,94],[47.5,96],[49.5,98],[51.5,100],[53.5,102],[55.5,104],[57.5,106],[59.5,108],[61.5,110],[63.5,112],[65.0,114],[66.5,116],[68.0,118],[69.0,120],[69.5,122],[70.5,124],[94.5,124],[95.5,122],[96.0,120],[97.0,118],[98.5,116],[100.0,114],[101.5,112],[103.5,110],[105.5,108],[107.5,106],[109.5,104],[111.5,102],[113.5,100],[115.5,98],[117.5,96],[119.5,94],[121.5,92],[123.5,90],[125.5,88],[127.5,86],[129.0,84],[130.5,82],[132.5,80],[134.0,78],[135.5,76],[137.0,74],[138.0,72],[139.5,70],[141.0,68],[142.0,66],[143.0,64],[144.0,62],[145.0,60],[145.5,58],[146.5,56],[147.0,54],[147.5,52],[148.0,50],[148.5,48],[149.0,46],[149.0,44],[149.0,42],[149.0,40],[149.0,38],[149.0,36],[149.0,34],[148.5,32],[148.0,30],[147.5,28],[146.5,26],[146.0,24],[145.0,22],[143.5,20],[142.0,18],[140.0,16],[138.0,14],[136.0,12],[133.0,10],[131.0,8],[129.0,6]],"LOW":[[70.5,124],[70.5,126],[70.5,128],[70.5,130],[69.5,132],[68.5,134],[67.5,136],[66.5,138],[64.5,140],[63.5,142],[61.5,144],[59.5,146],[57.5,148],[55.5,150],[54.0,152],[52.0,154],[50.0,156],[48.5,158],[46.5,160],[45.0,162],[43.0,164],[41.5,166],[40.0,168],[38.5,170],[37.0,172],[36.0,174],[34.0,176],[33.0,178],[32.0,180],[30.5,182],[29.0,184],[28.0,186],[27.0,188],[26.0,190],[25.0,192],[24.0,194],[23.5,196],[22.5,198],[22.0,200],[21.0,202],[20.5,204],[20.0,206],[19.0,208],[19.0,210],[18.0,212],[18.0,214],[18.0,216],[17.0,218],[17.0,220],[17.0,222],[17.0,224],[17.0,226],[17.0,228],[17.0,230],[17.0,232],[18.0,234],[18.0,236],[19.0,238],[19.0,240],[20.0,242],[21.0,244],[21.5,246],[22.5,248],[24.0,250],[25.0,252],[27.0,254],[29.0,256],[32.0,258],[34.0,260],[36.0,262],[129.0,262],[131.0,260],[133.0,258],[136.0,256],[138.0,254],[140.0,252],[141.0,250],[142.5,248],[143.5,246],[144.0,244],[145.0,242],[146.0,240],[146.0,238],[147.0,236],[147.0,234],[148.0,232],[148.0,230],[148.0,228],[148.0,226],[148.0,224],[148.0,222],[148.0,220],[148.0,218],[147.0,216],[147.0,214],[147.0,212],[146.0,210],[146.0,208],[145.0,206],[144.5,204],[144.0,202],[143.0,200],[142.5,198],[141.5,196],[141.0,194],[140.0,192],[139.0,190],[138.0,188],[137.0,186],[136.0,184],[134.5,182],[133.0,180],[132.0,178],[131.0,176],[129.0,174],[128.0,172],[126.5,170],[125.0,168],[123.5,166],[122.0,164],[120.0,162],[118.5,160],[116.5,158],[115.0,156],[113.0,154],[111.0,152],[109.5,150],[107.5,148],[105.5,146],[103.5,144],[101.5,142],[100.5,140],[98.5,138],[97.5,136],[96.5,134],[95.5,132],[94.5,130],[94.5,128],[94.5,126],[94.5,124]],"YN":124,"CX":83,"CYP":134,"S":6685}
  const OX = 55, OY = 4, PX = 138, PY = 138          // canvas offset of the glass picture, and the pivot (canvas coordinates)
  const S = DATA.S, K = 0.465, KC = 0.465, R0 = 46, F0 = 0.22, TURN = 1.2, DRAIN_END = 58, STREAM_END = 58.4
  const CAN = 277, FRAME = 33, DEBUG = false
  const cv = W.cv, glass = W.glass
  const mk = (a) => a.map((p) => [p[0] + OX, p[1] + OY])
  const UP = mk(DATA.UP), LOW = mk(DATA.LOW), NECK = [DATA.CX + OX, DATA.YN + OY]
  const DARK = (10 << 16) | (10 << 8) | 11, GOLD0 = 0xf0c868, GOLD1 = 0xe0a040, HI = 0xffde82
  const clamp = (v, a, b) => (v < a ? a : v > b ? b : v)

  // ---- polygons: keep the side of a line (a*x + b*y >= c); area; rotation about the pivot ----
  const clip = (p, a, b, c) => {
    const out = [], n = p.length
    if (!n) return out
    let prev = p[n - 1], pv = a * prev[0] + b * prev[1] - c
    for (let i = 0; i < n; i++) {
      const cur = p[i], cvv = a * cur[0] + b * cur[1] - c
      if (cvv >= 0) {
        if (pv < 0) { const t = pv / (pv - cvv); out.push([prev[0] + (cur[0] - prev[0]) * t, prev[1] + (cur[1] - prev[1]) * t]) }
        out.push(cur)
      } else if (pv >= 0) { const t = pv / (pv - cvv); out.push([prev[0] + (cur[0] - prev[0]) * t, prev[1] + (cur[1] - prev[1]) * t]) }
      prev = cur; pv = cvv
    }
    return out
  }
  const area = (p) => { let s = 0; for (let i = 0, n = p.length; i < n; i++) { const a = p[i], b = p[(i + 1) % n]; s += a[0] * b[1] - b[0] * a[1] } return Math.abs(s) / 2 }
  const rot = (p, deg) => {
    const r = deg * Math.PI / 180, co = Math.cos(r), si = Math.sin(r)
    return p.map((q) => [PX + (q[0] - PX) * co - (q[1] - PY) * si, PY + (q[0] - PX) * si + (q[1] - PY) * co])
  }
  const yRange = (p) => { let lo = 1e9, hi = -1e9; for (const q of p) { if (q[1] < lo) lo = q[1]; if (q[1] > hi) hi = q[1] } return [lo, hi] }

  // ---- sand of a bulb: surface(X) = c + cone * |X - nx| (a pile; cone 0 = level), or a level surface with a crater of depth d ----
  // sand(): [left, right] polygons; empty(): the rest of the bulb as convex pieces (they overlap by 2 px at X = nx so no seam shows)
  const halves = (poly, nx) => [clip(poly, -1, 0, -(nx + 1)), clip(poly, 1, 0, nx - 1)]
  const sand = (poly, nx, c, cone, d) => {
    const h = halves(poly, nx)
    if (d > 0) {
      const sl = d / R0
      return [clip(clip(h[0], 0, 1, c), -sl, 1, c + d - sl * nx), clip(clip(h[1], 0, 1, c), sl, 1, c + d + sl * nx)]
    }
    return [clip(h[0], cone, 1, c + cone * nx), clip(h[1], -cone, 1, c - cone * nx)]
  }
  const empty = (poly, nx, c, cone, d) => {
    const h = halves(poly, nx), out = []
    if (d > 0) {
      const sl = d / R0
      out.push(clip(h[0], 0, -1, -c), clip(h[0], sl, -1, -(c + d) + sl * nx), clip(h[1], 0, -1, -c), clip(h[1], -sl, -1, -(c + d) - sl * nx))
    } else {
      out.push(clip(h[0], -cone, -1, -(c + cone * nx)), clip(h[1], cone, -1, -c + cone * nx))
    }
    return out
  }
  const sandArea = (poly, nx, c, cone, d) => { const g = sand(poly, nx, c, cone, d); return area(g[0]) + area(g[1]) }
  // a thin lit strip along the surface of the sand (3 px below it)
  const strips = (poly, nx, c, cone, d) => {
    const g = sand(poly, nx, c, cone, d)
    if (d > 0) {
      const sl = d / R0
      return [clip(g[0], 0, -1, -(c + 3)), clip(g[0], sl, -1, -(c + d + 3) + sl * nx), clip(g[1], 0, -1, -(c + 3)), clip(g[1], -sl, -1, -(c + d + 3) - sl * nx)]
    }
    return [clip(g[0], -cone, -1, -(c + 3 + cone * nx)), clip(g[1], cone, -1, -(c + 3) + cone * nx)]
  }
  const solve = (poly, nx, target, cone, d) => {       // level c so that the sand has `target` area (area falls as c grows)
    const yr = yRange(poly); let lo = yr[0] - 2, hi = yr[1] + 2
    for (let i = 0; i < 13; i++) { const mid = (lo + hi) / 2; if (sandArea(poly, nx, mid, cone, d) > target) lo = mid; else hi = mid }
    return hi
  }

  // ---- drawing ----
  const PTS = []; const PP = { data_array: null, color: 0 }, CL = { x: 0, y: 0, w: CAN, h: CAN }, RS = { x1: 0, y1: 0, x2: 0, y2: 0, color: 0 }
  const poly = (p, color) => {
    const n = p.length; if (n < 3) return
    while (PTS.length < n + 1) PTS.push({ x: 0, y: 0 })
    for (let i = 0; i < n; i++) { PTS[i].x = Math.round(p[i][0]); PTS[i].y = Math.round(p[i][1]) }
    PTS[n].x = PTS[0].x; PTS[n].y = PTS[0].y
    PP.data_array = PTS.slice(0, n + 1); PP.color = color; cv.drawPoly(PP)
  }
  const rect = (x1, y1, x2, y2, color) => { RS.x1 = Math.round(x1); RS.y1 = Math.round(y1); RS.x2 = Math.round(x2); RS.y2 = Math.round(y2); RS.color = color; cv.drawRect(RS) }

  // ---- the state of the glass at a moment ----
  const state = (d) => {
    const m = d.getMinutes(), tt = d.getSeconds() + d.getMilliseconds() / 1000, o = m % 2
    if (tt < TURN) {                                            // turning: 0 -> 180 degrees (to the odd orientation) or 180 -> 360
      const p = tt / TURN, e = p < 0.5 ? 4 * p * p * p : 1 - Math.pow(-2 * p + 2, 3) / 2, phi = 180 * e
      const pour = clamp((phi - 90) / 90, 0, 1)
      return { ang: (o ? 0 : 180) + phi, src: o ? LOW : UP, dst: o ? UP : LOW, q: F0 * pour * pour * (3 - 2 * pour), cone: clamp(1 - phi / 50, 0, 1) * K, crater: 0, stream: phi > 120 && pour > 0.05, dust: 0 }
    }
    const g = clamp((tt - TURN) / (DRAIN_END - TURN), 0, 1)
    return { ang: o * 180, src: o ? LOW : UP, dst: o ? UP : LOW, q: F0 + (1 - F0) * g, cone: 0, crater: KC * R0 * Math.min(1, 3 * g), stream: tt < STREAM_END, dust: tt < STREAM_END + 0.8 ? clamp((0.22 - (1 - (F0 + (1 - F0) * g))) / 0.22, 0, 1) : 0 }
  }

  const frame = () => {
    const now = Date.now(), st = state(new Date(now))
    try { glass.setProperty(ui.prop.ANGLE, Math.round(st.ang) % 360) } catch (e) {}
    cv.clear(CL)
    const nk = rot([NECK], st.ang)[0], nx = nk[0], ny = nk[1]
    const srcW = rot(st.src, st.ang), dstW = rot(st.dst, st.ang)
    const aS = (1 - st.q) * S, aD = st.q * S
    let dstTop = null
    if (aD > 12) { const c = solve(dstW, nx, aD, K, 0); for (const g of empty(dstW, nx, c, K, 0)) poly(g, DARK); for (const g of strips(dstW, nx, c, K, 0)) poly(g, HI); dstTop = c } else poly(dstW, DARK)
    if (aS > 12) { const c = solve(srcW, nx, aS, st.cone, st.crater); for (const g of empty(srcW, nx, c, st.cone, st.crater)) poly(g, DARK); for (const g of strips(srcW, nx, c, st.cone, st.crater)) poly(g, HI) } else poly(srcW, DARK)
    if (st.dust > 0) {                                          // fine dust drifting down the funnel to the neck, thicker as the bulb empties
      const n = Math.round(16 * st.dust), t = now * 0.00035
      for (let i = 0; i < n; i++) {
        const ph = (t + i * 0.618) % 1, dy = 78 * (1 - ph), w = 3 + dy * 0.42
        const h = Math.sin(i * 12.9898) * 43758.5453, x = nx + (h - Math.floor(h) - 0.5) * 2 * w, y = ny - dy - 2
        rect(x, y, x + 1, y + 1, i % 3 ? GOLD0 : HI)
      }
    }
    if (st.stream) {                                            // a thin stream and grains falling from the neck to the pile (or the floor)
      const yr = yRange(dstW), stop = dstTop === null ? yr[1] - 2 : dstTop + 1
      if (stop > ny) {
        rect(nx - 1, ny, nx + 1, stop, GOLD1)
        const L = stop - ny, t = now * 0.14
        for (let i = 0; i < 9; i++) {
          const y = ny + ((t + i * L / 9 + (i * 37) % 11) % L), x = nx + ((i * 5) % 5) - 2
          rect(x, y, x + 1, y + 2, i % 2 ? GOLD0 : GOLD1)
        }
      }
    }
  }

  // ---- loop: a chain of timeouts, only while the face is on screen ----
  let timer = null, running = false, startedAt = Date.now(), nF = 0, msF = 0, tLog = 0
  const tick = () => {
    timer = null; if (!running) return
    const t0 = Date.now()
    try { frame() } catch (e) { if (DEBUG) console.log('[hourglass] ' + e) }
    nF++; msF += Date.now() - t0
    if (DEBUG && t0 - tLog >= 5000) { if (tLog) console.log('[hourglass] ' + (nF * 1000 / (t0 - tLog)).toFixed(1) + ' fps, ' + (msF / nF).toFixed(1) + ' ms'); tLog = t0; nF = 0; msF = 0 }
    try { timer = setTimeout(tick, Math.max(0, FRAME - (Date.now() - t0))) } catch (e) {}
  }
  const start = () => { if (running) return; running = true; tLog = Date.now(); tick() }
  const stop = () => { running = false; if (timer) { try { clearTimeout(timer) } catch (e) {} timer = null } }
  const onPause = () => { if (Date.now() - startedAt < 1500) return; stop() }
  const onResume = () => { if (Date.now() - startedAt < 1500) return; start() }
  ui.createWidget(ui.widget.WIDGET_DELEGATE, { pause_call: onPause, resume_call: onResume })
  start()
}
